ReplacementContent:
"                  {isDaysOpen && (
                    <div className="absolute left-0 mt-1 z-[50] min-w-[260px] max-w-[340px] rounded-xl border border-[#2a2a2a] bg-[#0c0c0c] py-1.5 shadow-xl">
                      {allTransportRangeOptions.map((option) => {
                        const selectedVal = `${transportStartDate}|${selectedTransportDays}`;
                        const isSelected = option.value === selectedVal;

                        return (
                          <button
                            key={option.value}
                            type="button"
                            onClick={() => {
                              const [sDate, daysStr] = option.value.split("|");
                              updateField(service.id, "serviceDate", sDate);
                              updateField(service.id, "days", Number(daysStr));
                              setIsDaysOpen(false);
                            }}
                            className={`flex w-full items-center px-4 py-2 text-left text-[10px] whitespace-nowrap cursor-pointer select-none transition-colors ${
                              isSelected 
                                ? "bg-yellow-500/15 text-yellow-400 font-semibold" 
                                : "text-white hover:bg-yellow-500/10"
                            }`}
                          >
                            {option.label}
                          </button>
                        );
                      })}
                    </div>
                  )}"

